-- Docs Health schema for PostgreSQL (generated by scripts/export_schema.py)
-- Safe to run in an empty schema. Tables are created in dependency order.

CREATE TABLE IF NOT EXISTS app_settings (
	key VARCHAR(100) NOT NULL, 
	value JSONB NOT NULL, 
	updated_by VARCHAR(120), 
	updated_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (key)
);


CREATE TABLE IF NOT EXISTS audit_log (
	id SERIAL NOT NULL, 
	entity_type VARCHAR(40) NOT NULL, 
	entity_id INTEGER, 
	action VARCHAR(60) NOT NULL, 
	actor VARCHAR(120) NOT NULL, 
	details JSONB NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id)
);

CREATE INDEX IF NOT EXISTS ix_audit_log_action ON audit_log (action);
CREATE INDEX IF NOT EXISTS ix_audit_log_created_at ON audit_log (created_at);
CREATE INDEX IF NOT EXISTS ix_audit_log_entity_id ON audit_log (entity_id);
CREATE INDEX IF NOT EXISTS ix_audit_log_entity_type ON audit_log (entity_type);

CREATE TABLE IF NOT EXISTS consent_templates (
	id SERIAL NOT NULL, 
	name VARCHAR(200) NOT NULL, 
	body TEXT NOT NULL, 
	version INTEGER DEFAULT '1' NOT NULL, 
	is_active BOOLEAN DEFAULT true NOT NULL, 
	created_by VARCHAR(120), 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (name)
);


CREATE TABLE IF NOT EXISTS drug_interaction_rules (
	id SERIAL NOT NULL, 
	drug_a VARCHAR(200) NOT NULL, 
	drug_b VARCHAR(200) NOT NULL, 
	severity VARCHAR(10) DEFAULT 'moderate' NOT NULL, 
	message VARCHAR(500) NOT NULL, 
	source VARCHAR(200), 
	is_active BOOLEAN DEFAULT true NOT NULL, 
	created_by VARCHAR(120), 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_drug_rule_pair UNIQUE (drug_a, drug_b), 
	CONSTRAINT ck_rule_severity CHECK (severity in ('minor','moderate','major'))
);

CREATE INDEX IF NOT EXISTS ix_drug_interaction_rules_drug_a ON drug_interaction_rules (drug_a);
CREATE INDEX IF NOT EXISTS ix_drug_interaction_rules_drug_b ON drug_interaction_rules (drug_b);

CREATE TABLE IF NOT EXISTS email_messages (
	id SERIAL NOT NULL, 
	message_id VARCHAR(500) NOT NULL, 
	direction VARCHAR(10) NOT NULL, 
	source VARCHAR(20) NOT NULL, 
	from_address VARCHAR(255) NOT NULL, 
	from_name VARCHAR(200), 
	to_address VARCHAR(255) NOT NULL, 
	subject VARCHAR(500) NOT NULL, 
	body_text TEXT NOT NULL, 
	body_raw TEXT, 
	redirect_to VARCHAR(255), 
	in_reply_to VARCHAR(500), 
	request_id INTEGER, 
	send_status VARCHAR(20), 
	send_error TEXT, 
	delivery_method VARCHAR(20), 
	mailbox_id INTEGER, 
	provider_message_id VARCHAR(300), 
	conversation_id VARCHAR(300), 
	delivered_at TIMESTAMP WITH TIME ZONE, 
	sent_by VARCHAR(120), 
	received_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id)
);

CREATE INDEX IF NOT EXISTS ix_email_messages_conversation_id ON email_messages (conversation_id);
CREATE INDEX IF NOT EXISTS ix_email_messages_from_address ON email_messages (from_address);
CREATE INDEX IF NOT EXISTS ix_email_messages_mailbox_id ON email_messages (mailbox_id);
CREATE UNIQUE INDEX IF NOT EXISTS ix_email_messages_message_id ON email_messages (message_id);
CREATE INDEX IF NOT EXISTS ix_email_messages_request_id ON email_messages (request_id);

CREATE TABLE IF NOT EXISTS integration_connections (
	id SERIAL NOT NULL, 
	provider VARCHAR(30) NOT NULL, 
	auth_mode VARCHAR(20) NOT NULL, 
	tenant_id VARCHAR(100), 
	client_id VARCHAR(100), 
	client_secret_encrypted TEXT, 
	client_secret_hint VARCHAR(10), 
	status VARCHAR(30) NOT NULL, 
	connected_account VARCHAR(255), 
	connected_name VARCHAR(255), 
	scopes TEXT, 
	refresh_token_encrypted TEXT, 
	token_expires_at TIMESTAMP WITH TIME ZONE, 
	poll_interval_seconds INTEGER, 
	last_error TEXT, 
	connected_by VARCHAR(120), 
	connected_at TIMESTAMP WITH TIME ZONE, 
	updated_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	UNIQUE (provider)
);


CREATE TABLE IF NOT EXISTS oauth_states (
	id SERIAL NOT NULL, 
	state_hash VARCHAR(64) NOT NULL, 
	provider VARCHAR(30) NOT NULL, 
	flow VARCHAR(20) NOT NULL, 
	code_verifier_encrypted TEXT, 
	created_by VARCHAR(120) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	expires_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	used_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id)
);

CREATE UNIQUE INDEX IF NOT EXISTS ix_oauth_states_state_hash ON oauth_states (state_hash);

CREATE TABLE IF NOT EXISTS payers (
	id SERIAL NOT NULL, 
	name VARCHAR(200) NOT NULL, 
	payer_code VARCHAR(40) NOT NULL, 
	aliases JSONB NOT NULL, 
	electronic_payer_id VARCHAR(20), 
	financial_category VARCHAR(40), 
	claims_addresses JSONB, 
	PRIMARY KEY (id), 
	UNIQUE (name), 
	UNIQUE (payer_code)
);

CREATE INDEX IF NOT EXISTS ix_payers_electronic_payer_id ON payers (electronic_payer_id);

CREATE TABLE IF NOT EXISTS providers (
	id SERIAL NOT NULL, 
	created_by VARCHAR(120), 
	updated_by VARCHAR(120), 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now(), 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now(), 
	full_name VARCHAR(200) NOT NULL, 
	specialty VARCHAR(120) NOT NULL, 
	npi VARCHAR(20) NOT NULL, 
	location VARCHAR(200) NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (npi)
);


CREATE TABLE IF NOT EXISTS record_history (
	id SERIAL NOT NULL, 
	table_name VARCHAR(60) NOT NULL, 
	record_id INTEGER NOT NULL, 
	operation VARCHAR(6) NOT NULL, 
	changed_by VARCHAR(120) NOT NULL, 
	changed_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	changes JSONB DEFAULT '{}' NOT NULL, 
	PRIMARY KEY (id)
);

CREATE INDEX IF NOT EXISTS ix_record_history_changed_at ON record_history (changed_at);
CREATE INDEX IF NOT EXISTS ix_record_history_record_id ON record_history (record_id);
CREATE INDEX IF NOT EXISTS ix_record_history_table_name ON record_history (table_name);

CREATE TABLE IF NOT EXISTS users (
	id SERIAL NOT NULL, 
	email VARCHAR(255) NOT NULL, 
	full_name VARCHAR(200) NOT NULL, 
	role VARCHAR(30) NOT NULL, 
	password_hash VARCHAR(255) NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	password_changed_at TIMESTAMP WITH TIME ZONE, 
	token_version INTEGER, 
	failed_logins INTEGER, 
	first_failed_at TIMESTAMP WITH TIME ZONE, 
	locked_until TIMESTAMP WITH TIME ZONE, 
	last_login_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id)
);

CREATE UNIQUE INDEX IF NOT EXISTS ix_users_email ON users (email);

CREATE TABLE IF NOT EXISTS integration_mailboxes (
	id SERIAL NOT NULL, 
	connection_id INTEGER NOT NULL, 
	address VARCHAR(255) NOT NULL, 
	display_name VARCHAR(200), 
	folder VARCHAR(200) NOT NULL, 
	enabled BOOLEAN NOT NULL, 
	process_inbound BOOLEAN NOT NULL, 
	reply_from_same_mailbox BOOLEAN NOT NULL, 
	mark_as_read BOOLEAN NOT NULL, 
	is_default_sender BOOLEAN NOT NULL, 
	last_polled_at TIMESTAMP WITH TIME ZONE, 
	last_poll_count INTEGER, 
	last_received_at TIMESTAMP WITH TIME ZONE, 
	last_error TEXT, 
	skip_sender_domains TEXT, 
	skipped_internal_total INTEGER, 
	unread_count INTEGER, 
	total_count INTEGER, 
	counts_at TIMESTAMP WITH TIME ZONE, 
	created_by VARCHAR(120), 
	created_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(connection_id) REFERENCES integration_connections (id) ON DELETE CASCADE, 
	UNIQUE (address)
);

CREATE INDEX IF NOT EXISTS ix_integration_mailboxes_connection_id ON integration_mailboxes (connection_id);

CREATE TABLE IF NOT EXISTS password_reset_tokens (
	id SERIAL NOT NULL, 
	user_id INTEGER NOT NULL, 
	token_hash VARCHAR(64) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	expires_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	used_at TIMESTAMP WITH TIME ZONE, 
	requested_ip VARCHAR(64), 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE UNIQUE INDEX IF NOT EXISTS ix_password_reset_tokens_token_hash ON password_reset_tokens (token_hash);
CREATE INDEX IF NOT EXISTS ix_password_reset_tokens_user_id ON password_reset_tokens (user_id);

CREATE TABLE IF NOT EXISTS patients (
	id SERIAL NOT NULL, 
	created_by VARCHAR(120), 
	updated_by VARCHAR(120), 
	mrn VARCHAR(30) NOT NULL, 
	prefix VARCHAR(20), 
	first_name VARCHAR(100) NOT NULL, 
	middle_name VARCHAR(100), 
	last_name VARCHAR(100) NOT NULL, 
	suffix VARCHAR(20), 
	preferred_name VARCHAR(100), 
	previous_name VARCHAR(200), 
	is_test_patient BOOLEAN, 
	marital_status VARCHAR(30), 
	date_of_birth DATE, 
	sex VARCHAR(20), 
	ssn_encrypted TEXT, 
	ssn_last4 VARCHAR(4), 
	drivers_license_encrypted TEXT, 
	drivers_license_last4 VARCHAR(4), 
	drivers_license_state VARCHAR(2), 
	phone VARCHAR(30), 
	home_phone VARCHAR(30), 
	work_phone VARCHAR(30), 
	preferred_contact_method VARCHAR(20), 
	email VARCHAR(255), 
	address_line1 VARCHAR(200), 
	address_line2 VARCHAR(200), 
	city VARCHAR(100), 
	state VARCHAR(40), 
	postal_code VARCHAR(20), 
	preferred_provider_id INTEGER, 
	notes TEXT, 
	pcp_name VARCHAR(200), 
	pms_id VARCHAR(60), 
	portal_status VARCHAR(10), 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(preferred_provider_id) REFERENCES providers (id) ON DELETE SET NULL
);

CREATE INDEX IF NOT EXISTS ix_patients_date_of_birth ON patients (date_of_birth);
CREATE INDEX IF NOT EXISTS ix_patients_email ON patients (email);
CREATE INDEX IF NOT EXISTS ix_patients_first_name ON patients (first_name);
CREATE INDEX IF NOT EXISTS ix_patients_last_name ON patients (last_name);
CREATE UNIQUE INDEX IF NOT EXISTS ix_patients_mrn ON patients (mrn);
CREATE INDEX IF NOT EXISTS ix_patients_phone ON patients (phone);
CREATE INDEX IF NOT EXISTS ix_patients_pms_id ON patients (pms_id);

CREATE TABLE IF NOT EXISTS payer_plans (
	id SERIAL NOT NULL, 
	payer_id INTEGER NOT NULL, 
	name VARCHAR(200) NOT NULL, 
	plan_type VARCHAR(20) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (payer_id, name), 
	FOREIGN KEY(payer_id) REFERENCES payers (id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS ix_payer_plans_payer_id ON payer_plans (payer_id);

CREATE TABLE IF NOT EXISTS provider_availability (
	id SERIAL NOT NULL, 
	provider_id INTEGER NOT NULL, 
	weekday INTEGER NOT NULL, 
	start_time TIME WITHOUT TIME ZONE NOT NULL, 
	end_time TIME WITHOUT TIME ZONE NOT NULL, 
	slot_minutes INTEGER NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(provider_id) REFERENCES providers (id) ON DELETE CASCADE
);


CREATE TABLE IF NOT EXISTS provider_blocks (
	id SERIAL NOT NULL, 
	updated_by VARCHAR(120), 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now(), 
	provider_id INTEGER NOT NULL, 
	start_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	end_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	reason VARCHAR(200), 
	created_by VARCHAR(120) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(provider_id) REFERENCES providers (id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS ix_provider_blocks_provider_id ON provider_blocks (provider_id);
CREATE INDEX IF NOT EXISTS ix_provider_blocks_start_at ON provider_blocks (start_at);

CREATE TABLE IF NOT EXISTS provider_networks (
	id SERIAL NOT NULL, 
	provider_id INTEGER NOT NULL, 
	payer_id INTEGER NOT NULL, 
	in_network BOOLEAN NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (provider_id, payer_id), 
	FOREIGN KEY(provider_id) REFERENCES providers (id) ON DELETE CASCADE, 
	FOREIGN KEY(payer_id) REFERENCES payers (id) ON DELETE CASCADE
);


CREATE TABLE IF NOT EXISTS appointments (
	id SERIAL NOT NULL, 
	updated_by VARCHAR(120), 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now(), 
	patient_id INTEGER NOT NULL, 
	provider_id INTEGER NOT NULL, 
	start_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	end_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	visit_reason VARCHAR(300), 
	source_request_id INTEGER, 
	booked_by VARCHAR(120) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	cancelled_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(patient_id) REFERENCES patients (id) ON DELETE CASCADE, 
	FOREIGN KEY(provider_id) REFERENCES providers (id)
);

CREATE INDEX IF NOT EXISTS ix_appointments_patient_id ON appointments (patient_id);
CREATE INDEX IF NOT EXISTS ix_appointments_provider_id ON appointments (provider_id);
CREATE INDEX IF NOT EXISTS ix_appointments_start_at ON appointments (start_at);

CREATE TABLE IF NOT EXISTS clinical_orders (
	id SERIAL NOT NULL, 
	patient_id INTEGER NOT NULL, 
	order_type VARCHAR(10) NOT NULL, 
	description VARCHAR(500) NOT NULL, 
	status VARCHAR(10) DEFAULT 'draft' NOT NULL, 
	ordered_by_provider_id INTEGER, 
	ordered_on DATE, 
	due_on DATE, 
	completed_on DATE, 
	result_note TEXT, 
	created_by VARCHAR(120), 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_order_type CHECK (order_type in ('lab','imaging','referral','other')), 
	CONSTRAINT ck_order_status CHECK (status in ('draft','ordered','completed','cancelled')), 
	FOREIGN KEY(patient_id) REFERENCES patients (id) ON DELETE CASCADE, 
	FOREIGN KEY(ordered_by_provider_id) REFERENCES providers (id) ON DELETE SET NULL
);

CREATE INDEX IF NOT EXISTS ix_clinical_orders_patient_id ON clinical_orders (patient_id);

CREATE TABLE IF NOT EXISTS guarantors (
	id SERIAL NOT NULL, 
	created_by VARCHAR(120), 
	updated_by VARCHAR(120), 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now(), 
	patient_id INTEGER NOT NULL, 
	same_as_patient BOOLEAN, 
	relationship_to_patient VARCHAR(30), 
	first_name VARCHAR(100), 
	last_name VARCHAR(100), 
	date_of_birth DATE, 
	phone VARCHAR(30), 
	email VARCHAR(255), 
	address_line1 VARCHAR(200), 
	city VARCHAR(100), 
	state VARCHAR(40), 
	postal_code VARCHAR(20), 
	updated_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	UNIQUE (patient_id), 
	FOREIGN KEY(patient_id) REFERENCES patients (id) ON DELETE CASCADE
);


CREATE TABLE IF NOT EXISTS insurance_policies (
	id SERIAL NOT NULL, 
	created_by VARCHAR(120), 
	updated_by VARCHAR(120), 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now(), 
	patient_id INTEGER NOT NULL, 
	payer_id INTEGER NOT NULL, 
	member_id VARCHAR(60) NOT NULL, 
	group_number VARCHAR(60), 
	subscriber_name VARCHAR(200), 
	relationship_to_subscriber VARCHAR(30) NOT NULL, 
	is_primary BOOLEAN NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	coverage_order VARCHAR(10), 
	plan_name VARCHAR(200), 
	policy_type VARCHAR(20), 
	claims_address VARCHAR(300), 
	notes VARCHAR(500), 
	requires_referral BOOLEAN, 
	requires_precert_inpatient BOOLEAN, 
	requires_preauth_outpatient BOOLEAN, 
	holder_first_name VARCHAR(100), 
	holder_last_name VARCHAR(100), 
	holder_date_of_birth DATE, 
	eligibility_status VARCHAR(20), 
	copay_amount NUMERIC(10, 2), 
	coinsurance_pct NUMERIC(5, 2), 
	deductible NUMERIC(10, 2), 
	remaining_deductible NUMERIC(10, 2), 
	out_of_pocket NUMERIC(10, 2), 
	remaining_out_of_pocket NUMERIC(10, 2), 
	effective_date DATE, 
	end_date DATE, 
	archived_at TIMESTAMP WITH TIME ZONE, 
	archived_by VARCHAR(120), 
	last_eligibility_check_id INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(patient_id) REFERENCES patients (id) ON DELETE CASCADE, 
	FOREIGN KEY(payer_id) REFERENCES payers (id)
);

CREATE INDEX IF NOT EXISTS ix_insurance_policies_member_id ON insurance_policies (member_id);
CREATE INDEX IF NOT EXISTS ix_insurance_policies_patient_id ON insurance_policies (patient_id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_policy_active_order ON insurance_policies (patient_id, COALESCE(coverage_order, CASE WHEN is_primary THEN 'primary' ELSE 'secondary' END)) WHERE is_active;

CREATE TABLE IF NOT EXISTS intramail (
	id SERIAL NOT NULL, 
	sender_id INTEGER NOT NULL, 
	recipient_id INTEGER NOT NULL, 
	patient_id INTEGER, 
	subject VARCHAR(200) NOT NULL, 
	body TEXT NOT NULL, 
	sent_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	read_at TIMESTAMP WITH TIME ZONE, 
	deleted_by_sender BOOLEAN DEFAULT false NOT NULL, 
	deleted_by_recipient BOOLEAN DEFAULT false NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(sender_id) REFERENCES users (id) ON DELETE CASCADE, 
	FOREIGN KEY(recipient_id) REFERENCES users (id) ON DELETE CASCADE, 
	FOREIGN KEY(patient_id) REFERENCES patients (id) ON DELETE SET NULL
);

CREATE INDEX IF NOT EXISTS ix_intramail_patient_id ON intramail (patient_id);
CREATE INDEX IF NOT EXISTS ix_intramail_recipient_id ON intramail (recipient_id);
CREATE INDEX IF NOT EXISTS ix_intramail_sender_id ON intramail (sender_id);
CREATE INDEX IF NOT EXISTS ix_intramail_sent_at ON intramail (sent_at);

CREATE TABLE IF NOT EXISTS mailbox_skipped_messages (
	id SERIAL NOT NULL, 
	mailbox_id INTEGER NOT NULL, 
	provider_message_id VARCHAR(512) NOT NULL, 
	kind VARCHAR(20) NOT NULL, 
	reason VARCHAR(300) NOT NULL, 
	from_address VARCHAR(255), 
	received_at TIMESTAMP WITH TIME ZONE, 
	created_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_mailbox_skipped_msg UNIQUE (mailbox_id, provider_message_id), 
	FOREIGN KEY(mailbox_id) REFERENCES integration_mailboxes (id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS ix_mailbox_skipped_messages_kind ON mailbox_skipped_messages (kind);
CREATE INDEX IF NOT EXISTS ix_mailbox_skipped_messages_mailbox_id ON mailbox_skipped_messages (mailbox_id);

CREATE TABLE IF NOT EXISTS medications (
	id SERIAL NOT NULL, 
	patient_id INTEGER NOT NULL, 
	drug_name VARCHAR(200) NOT NULL, 
	strength VARCHAR(60), 
	route VARCHAR(40), 
	frequency VARCHAR(100), 
	quantity INTEGER, 
	refills INTEGER, 
	prescriber_id INTEGER, 
	status VARCHAR(10) DEFAULT 'active' NOT NULL, 
	start_on DATE, 
	stop_on DATE, 
	instructions TEXT, 
	created_by VARCHAR(120), 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_med_status CHECK (status in ('active','stopped','completed')), 
	CONSTRAINT ck_med_quantity CHECK (quantity is null or quantity >= 0), 
	CONSTRAINT ck_med_refills CHECK (refills is null or refills >= 0), 
	FOREIGN KEY(patient_id) REFERENCES patients (id) ON DELETE CASCADE, 
	FOREIGN KEY(prescriber_id) REFERENCES providers (id) ON DELETE SET NULL
);

CREATE INDEX IF NOT EXISTS ix_medications_drug_name ON medications (drug_name);
CREATE INDEX IF NOT EXISTS ix_medications_patient_id ON medications (patient_id);

CREATE TABLE IF NOT EXISTS patient_alerts (
	id SERIAL NOT NULL, 
	patient_id INTEGER NOT NULL, 
	text VARCHAR(500) NOT NULL, 
	severity VARCHAR(10) DEFAULT 'info' NOT NULL, 
	is_active BOOLEAN DEFAULT true NOT NULL, 
	created_by VARCHAR(120), 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_alert_severity CHECK (severity in ('info','warning','critical')), 
	FOREIGN KEY(patient_id) REFERENCES patients (id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS ix_patient_alerts_patient_id ON patient_alerts (patient_id);

CREATE TABLE IF NOT EXISTS patient_allergies (
	id SERIAL NOT NULL, 
	patient_id INTEGER NOT NULL, 
	allergen VARCHAR(200) NOT NULL, 
	reaction VARCHAR(300), 
	severity VARCHAR(10), 
	status VARCHAR(10) DEFAULT 'active' NOT NULL, 
	noted_on DATE, 
	created_by VARCHAR(120), 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_allergy_status CHECK (status in ('active','inactive')), 
	CONSTRAINT ck_allergy_severity CHECK (severity is null or severity in ('mild','moderate','severe')), 
	FOREIGN KEY(patient_id) REFERENCES patients (id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS ix_patient_allergies_patient_id ON patient_allergies (patient_id);

CREATE TABLE IF NOT EXISTS patient_consents (
	id SERIAL NOT NULL, 
	patient_id INTEGER NOT NULL, 
	template_id INTEGER NOT NULL, 
	template_version INTEGER DEFAULT '1' NOT NULL, 
	status VARCHAR(10) DEFAULT 'pending' NOT NULL, 
	signed_on DATE, 
	signed_by_name VARCHAR(200), 
	expires_on DATE, 
	revoked_at TIMESTAMP WITH TIME ZONE, 
	created_by VARCHAR(120), 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_consent_status CHECK (status in ('pending','signed','revoked')), 
	FOREIGN KEY(patient_id) REFERENCES patients (id) ON DELETE CASCADE, 
	FOREIGN KEY(template_id) REFERENCES consent_templates (id) ON DELETE RESTRICT
);

CREATE INDEX IF NOT EXISTS ix_patient_consents_patient_id ON patient_consents (patient_id);
CREATE INDEX IF NOT EXISTS ix_patient_consents_template_id ON patient_consents (template_id);

CREATE TABLE IF NOT EXISTS patient_documents (
	id SERIAL NOT NULL, 
	patient_id INTEGER NOT NULL, 
	kind VARCHAR(40) NOT NULL, 
	filename VARCHAR(255) NOT NULL, 
	content_type VARCHAR(100) NOT NULL, 
	storage_path VARCHAR(500) NOT NULL, 
	size_bytes INTEGER NOT NULL, 
	uploaded_by VARCHAR(120) NOT NULL, 
	uploaded_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(patient_id) REFERENCES patients (id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS ix_patient_documents_patient_id ON patient_documents (patient_id);

CREATE TABLE IF NOT EXISTS patient_flags (
	id SERIAL NOT NULL, 
	patient_id INTEGER NOT NULL, 
	flag_type VARCHAR(60) NOT NULL, 
	note VARCHAR(300), 
	is_active BOOLEAN DEFAULT true NOT NULL, 
	created_by VARCHAR(120), 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(patient_id) REFERENCES patients (id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS ix_patient_flags_patient_id ON patient_flags (patient_id);

CREATE TABLE IF NOT EXISTS patient_links (
	id SERIAL NOT NULL, 
	patient_id INTEGER NOT NULL, 
	linked_patient_id INTEGER NOT NULL, 
	relationship_label VARCHAR(50), 
	created_by VARCHAR(120), 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_patient_link UNIQUE (patient_id, linked_patient_id), 
	CONSTRAINT ck_link_not_self CHECK (patient_id <> linked_patient_id), 
	FOREIGN KEY(patient_id) REFERENCES patients (id) ON DELETE CASCADE, 
	FOREIGN KEY(linked_patient_id) REFERENCES patients (id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS ix_patient_links_linked_patient_id ON patient_links (linked_patient_id);
CREATE INDEX IF NOT EXISTS ix_patient_links_patient_id ON patient_links (patient_id);

CREATE TABLE IF NOT EXISTS patient_notes (
	id SERIAL NOT NULL, 
	patient_id INTEGER NOT NULL, 
	kind VARCHAR(10) DEFAULT 'general' NOT NULL, 
	body TEXT NOT NULL, 
	created_by VARCHAR(120), 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_note_kind CHECK (kind in ('sticky','general','clinical')), 
	FOREIGN KEY(patient_id) REFERENCES patients (id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS ix_patient_notes_patient_id ON patient_notes (patient_id);

CREATE TABLE IF NOT EXISTS patient_reminders (
	id SERIAL NOT NULL, 
	patient_id INTEGER NOT NULL, 
	message VARCHAR(500) NOT NULL, 
	due_on DATE, 
	status VARCHAR(10) DEFAULT 'open' NOT NULL, 
	completed_at TIMESTAMP WITH TIME ZONE, 
	created_by VARCHAR(120), 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_reminder_status CHECK (status in ('open','done','cancelled')), 
	FOREIGN KEY(patient_id) REFERENCES patients (id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS ix_patient_reminders_due_on ON patient_reminders (due_on);
CREATE INDEX IF NOT EXISTS ix_patient_reminders_patient_id ON patient_reminders (patient_id);

CREATE TABLE IF NOT EXISTS phi_releases (
	id SERIAL NOT NULL, 
	updated_by VARCHAR(120), 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now(), 
	patient_id INTEGER NOT NULL, 
	recipient_name VARCHAR(200) NOT NULL, 
	relationship_to_patient VARCHAR(50), 
	phone VARCHAR(30), 
	may_discuss_appointments BOOLEAN, 
	may_discuss_billing BOOLEAN, 
	may_discuss_clinical BOOLEAN, 
	signed_on DATE, 
	expires_on DATE, 
	revoked_at TIMESTAMP WITH TIME ZONE, 
	created_by VARCHAR(120), 
	created_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(patient_id) REFERENCES patients (id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS ix_phi_releases_patient_id ON phi_releases (patient_id);

CREATE TABLE IF NOT EXISTS tasks (
	id SERIAL NOT NULL, 
	patient_id INTEGER, 
	title VARCHAR(200) NOT NULL, 
	description TEXT, 
	assigned_to_id INTEGER, 
	priority VARCHAR(10) DEFAULT 'normal' NOT NULL, 
	due_on DATE, 
	status VARCHAR(12) DEFAULT 'open' NOT NULL, 
	completed_at TIMESTAMP WITH TIME ZONE, 
	created_by VARCHAR(120), 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_task_status CHECK (status in ('open','in_progress','done','cancelled')), 
	CONSTRAINT ck_task_priority CHECK (priority in ('low','normal','high')), 
	FOREIGN KEY(patient_id) REFERENCES patients (id) ON DELETE CASCADE, 
	FOREIGN KEY(assigned_to_id) REFERENCES users (id) ON DELETE SET NULL
);

CREATE INDEX IF NOT EXISTS ix_tasks_assigned_to_id ON tasks (assigned_to_id);
CREATE INDEX IF NOT EXISTS ix_tasks_due_on ON tasks (due_on);
CREATE INDEX IF NOT EXISTS ix_tasks_patient_id ON tasks (patient_id);

CREATE TABLE IF NOT EXISTS portal_requests (
	id SERIAL NOT NULL, 
	created_by VARCHAR(120), 
	updated_by VARCHAR(120), 
	reference VARCHAR(20) NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	intent VARCHAR(30), 
	source_email_id INTEGER, 
	extracted JSONB NOT NULL, 
	patient_id INTEGER, 
	match_confidence FLOAT, 
	match_details JSONB NOT NULL, 
	provider_id INTEGER, 
	ai_confidence FLOAT, 
	ai_summary TEXT, 
	decision VARCHAR(20), 
	review_reasons JSONB NOT NULL, 
	draft_response TEXT, 
	draft_chart JSONB, 
	appointment_id INTEGER, 
	assigned_to VARCHAR(120), 
	priority VARCHAR(10) NOT NULL, 
	llm_provider VARCHAR(40), 
	resolution_note TEXT, 
	resolved_by VARCHAR(120), 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	first_response_at TIMESTAMP WITH TIME ZONE, 
	resolved_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(source_email_id) REFERENCES email_messages (id) ON DELETE SET NULL, 
	FOREIGN KEY(patient_id) REFERENCES patients (id) ON DELETE SET NULL, 
	FOREIGN KEY(provider_id) REFERENCES providers (id) ON DELETE SET NULL, 
	FOREIGN KEY(appointment_id) REFERENCES appointments (id) ON DELETE SET NULL
);

CREATE INDEX IF NOT EXISTS ix_portal_requests_created_at ON portal_requests (created_at);
CREATE INDEX IF NOT EXISTS ix_portal_requests_patient_id ON portal_requests (patient_id);
CREATE UNIQUE INDEX IF NOT EXISTS ix_portal_requests_reference ON portal_requests (reference);
CREATE INDEX IF NOT EXISTS ix_portal_requests_status ON portal_requests (status);

CREATE TABLE IF NOT EXISTS procedure_logs (
	id SERIAL NOT NULL, 
	patient_id INTEGER NOT NULL, 
	appointment_id INTEGER, 
	provider_id INTEGER, 
	cpt_code VARCHAR(5) NOT NULL, 
	icd10_code VARCHAR(8), 
	description VARCHAR(300), 
	units INTEGER DEFAULT '1' NOT NULL, 
	performed_on DATE NOT NULL, 
	created_by VARCHAR(120), 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_proc_units CHECK (units >= 1), 
	FOREIGN KEY(patient_id) REFERENCES patients (id) ON DELETE CASCADE, 
	FOREIGN KEY(appointment_id) REFERENCES appointments (id) ON DELETE SET NULL, 
	FOREIGN KEY(provider_id) REFERENCES providers (id) ON DELETE SET NULL
);

CREATE INDEX IF NOT EXISTS ix_procedure_logs_patient_id ON procedure_logs (patient_id);

CREATE TABLE IF NOT EXISTS eligibility_checks (
	id SERIAL NOT NULL, 
	patient_id INTEGER NOT NULL, 
	policy_id INTEGER, 
	provider_id INTEGER, 
	request_id INTEGER, 
	coverage_status VARCHAR(30) NOT NULL, 
	in_network BOOLEAN, 
	plan_name VARCHAR(200), 
	copay VARCHAR(40), 
	message TEXT, 
	raw_response JSONB NOT NULL, 
	checked_by VARCHAR(120) NOT NULL, 
	checked_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	date_of_service DATE, 
	npi_type VARCHAR(12), 
	npi VARCHAR(20), 
	payer_member_name VARCHAR(200), 
	payer_member_dob DATE, 
	payer_member_id VARCHAR(60), 
	plan_type VARCHAR(20), 
	plan_start DATE, 
	plan_end DATE, 
	eligibility_start DATE, 
	eligibility_end DATE, 
	raw_x12 TEXT, 
	discrepancies JSONB, 
	ai_summary TEXT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(patient_id) REFERENCES patients (id) ON DELETE CASCADE, 
	FOREIGN KEY(policy_id) REFERENCES insurance_policies (id) ON DELETE SET NULL, 
	FOREIGN KEY(provider_id) REFERENCES providers (id) ON DELETE SET NULL, 
	FOREIGN KEY(request_id) REFERENCES portal_requests (id) ON DELETE SET NULL
);

CREATE INDEX IF NOT EXISTS ix_eligibility_checks_patient_id ON eligibility_checks (patient_id);

CREATE TABLE IF NOT EXISTS eligibility_benefits (
	id SERIAL NOT NULL, 
	check_id INTEGER NOT NULL, 
	network VARCHAR(4) NOT NULL, 
	category VARCHAR(40) NOT NULL, 
	coverage_level VARCHAR(12) NOT NULL, 
	service_type_code VARCHAR(4) NOT NULL, 
	service_type VARCHAR(120) NOT NULL, 
	amount NUMERIC(10, 2), 
	percent NUMERIC(5, 2), 
	time_period VARCHAR(30), 
	auth_required BOOLEAN, 
	message VARCHAR(300), 
	PRIMARY KEY (id), 
	FOREIGN KEY(check_id) REFERENCES eligibility_checks (id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS ix_eligibility_benefits_check_id ON eligibility_benefits (check_id);

-- Circular references, added after all tables exist
ALTER TABLE email_messages ADD CONSTRAINT fk_email_request FOREIGN KEY (request_id) REFERENCES portal_requests (id) ON DELETE SET NULL;
ALTER TABLE appointments ADD CONSTRAINT fk_appt_request FOREIGN KEY (source_request_id) REFERENCES portal_requests (id) ON DELETE SET NULL;
